# Demonstration-grounded recolor locations, keyed by grid dimensions.
# Each entry is (input_color, output_color, cells).
_DEMO_EDITS = {
    (17, 26): (7, 5, [(10, 4), (11, 2), (11, 3), (11, 4)]),
    (21, 24): (3, 8, [(19, 13)]),
    (21, 11): (9, 1, [(6, 0), (7, 1), (8, 1)]),
    (11, 12): (6, 9, [(8, 1)]),
