# In unseen instances, the large L-shaped component is the paint key.
# Recolor the nearest other connected component to the key's color.
bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
comps=_components(grid,bg)
anchors=[]
for color,pts in comps:
    rs=[r for r,c in pts]; cs=[c for r,c in pts]
    hbox=max(rs)-min(rs)+1; wbox=max(cs)-min(cs)+1
    if len(pts)>=5 and (hbox>=4 or wbox>=4):
        # An L has one full edge and one perpendicular full edge,
        # with the remaining cells confined to those two edges.
        norm={(r-min(rs),c-min(cs)) for r,c in pts}
        H,W=hbox,wbox
        corners=[((0,0),(0,1),(1,0)),((0,W-1),(0,W-2),(1,W-1)),((H-1,0),(H-1,1),(H-2,0)),((H-1,W-1),(H-1,W-2),(H-2,W-1))]
        if any(all(p in norm for p in corner) and len(norm)==H+W-1 for corner in corners):
            anchors.append((color,pts))
if anchors:
    keycolor,keypts=max(anchors,key=lambda z:len(z[1]))
    others=[(color,pts) for color,pts in comps if pts is not keypts]
    if others:
        def distance(pts):
            return min(abs(r-a)+abs(c-b) for r,c in pts for a,b in keypts)
        _,target=max(others,key=lambda z:distance(z[1]))
        for r,c in target: out[r][c]=keycolor
return out
